ALTER TABLE inventory_movements DROP CONSTRAINT inventory_movements_movement_type_check;ALTER TABLE inventory_movements ADD CONSTRAINT inventory_movements_movement_type_check CHECK(movement_type IN('OPENING_BALANCE','MANUAL_ADJUSTMENT','GOODS_RECEIPT','PUT_AWAY','PICKING_RELOCATION'));
ALTER TABLE inventory_movements DROP CONSTRAINT inventory_movements_reason_code_check;ALTER TABLE inventory_movements ADD CONSTRAINT inventory_movements_reason_code_check CHECK(reason_code IN('INITIAL_LOAD','MANUAL_CORRECTION','FOUND','DAMAGE','OTHER','GOODS_RECEIPT','PUT_AWAY','PICKING_RELOCATION'));
ALTER TABLE inventory_reservations DROP CONSTRAINT inventory_reservations_status_check;ALTER TABLE inventory_reservations ADD CONSTRAINT inventory_reservations_status_check CHECK(status IN('ACTIVE','RELEASED','EXPIRED','CONSUMED'));
ALTER TABLE sales_orders ADD COLUMN fulfillment_status VARCHAR(16) NOT NULL DEFAULT 'NOT_STARTED' CHECK(fulfillment_status IN('NOT_STARTED','PICKING','PICKED','PACKING','PACKED'));
ALTER TABLE sales_order_lines ADD COLUMN picked_quantity NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(picked_quantity>=0 AND picked_quantity<=allocated_quantity),ADD COLUMN packed_quantity NUMERIC(19,6) NOT NULL DEFAULT 0 CHECK(packed_quantity>=0 AND packed_quantity<=picked_quantity);
CREATE TABLE pick_lists(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,sales_order_id UUID NOT NULL,sales_order_number_snapshot VARCHAR(32) NOT NULL,warehouse_id UUID NOT NULL,packing_location_id UUID NOT NULL,status VARCHAR(16) NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,sales_order_id),FOREIGN KEY(tenant_id,sales_order_id)REFERENCES sales_orders(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id,packing_location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id),CHECK(status IN('CREATED','IN_PROGRESS','COMPLETED','CANCELLED')));
CREATE TABLE pick_tasks(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,pick_list_id UUID NOT NULL,sales_order_id UUID NOT NULL,sales_order_line_id UUID NOT NULL,inventory_reservation_id UUID NOT NULL,reservation_allocation_id UUID NOT NULL,variant_id UUID NOT NULL,warehouse_id UUID NOT NULL,source_location_id UUID NOT NULL,destination_packing_location_id UUID NOT NULL,lot_id UUID,serial_id UUID,required_quantity NUMERIC(19,6) NOT NULL,picked_quantity NUMERIC(19,6) NOT NULL DEFAULT 0,unit_code VARCHAR(8) NOT NULL,status VARCHAR(16) NOT NULL,sequence INTEGER NOT NULL,completed_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,reservation_allocation_id),FOREIGN KEY(tenant_id,pick_list_id)REFERENCES pick_lists(tenant_id,id),FOREIGN KEY(tenant_id,sales_order_id,sales_order_line_id)REFERENCES sales_order_lines(tenant_id,sales_order_id,id),FOREIGN KEY(tenant_id,inventory_reservation_id,reservation_allocation_id)REFERENCES inventory_reservation_allocations(tenant_id,reservation_id,id),FOREIGN KEY(tenant_id,warehouse_id,source_location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id),FOREIGN KEY(tenant_id,warehouse_id,destination_packing_location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id),CHECK(required_quantity>0),CHECK(picked_quantity>=0 AND picked_quantity<=required_quantity),CHECK(status IN('PENDING','COMPLETED')));
CREATE TABLE inventory_reservation_consumptions(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,reservation_id UUID NOT NULL,reservation_allocation_id UUID NOT NULL,inventory_movement_id UUID NOT NULL,quantity NUMERIC(19,6) NOT NULL,consumed_at TIMESTAMPTZ NOT NULL,consumed_by UUID NOT NULL,UNIQUE(tenant_id,reservation_allocation_id),FOREIGN KEY(tenant_id,reservation_id,reservation_allocation_id)REFERENCES inventory_reservation_allocations(tenant_id,reservation_id,id),FOREIGN KEY(tenant_id,inventory_movement_id)REFERENCES inventory_movements(tenant_id,id),CHECK(quantity>0));
CREATE TABLE packing_sessions(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,sales_order_id UUID NOT NULL,pick_list_id UUID NOT NULL,packing_location_id UUID NOT NULL,status VARCHAR(16) NOT NULL,created_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,sales_order_id),UNIQUE(tenant_id,pick_list_id),FOREIGN KEY(tenant_id,pick_list_id)REFERENCES pick_lists(tenant_id,id),CHECK(status IN('OPEN','PACKED')));
CREATE TABLE fulfillment_packages(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,packing_session_id UUID NOT NULL,package_number VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL,weight_grams BIGINT,length_mm BIGINT,width_mm BIGINT,height_mm BIGINT,created_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,packing_session_id,package_number),FOREIGN KEY(tenant_id,packing_session_id)REFERENCES packing_sessions(tenant_id,id),CHECK(status IN('OPEN','PACKED')),CHECK(weight_grams IS NULL OR weight_grams>=0),CHECK(length_mm IS NULL OR length_mm>=0),CHECK(width_mm IS NULL OR width_mm>=0),CHECK(height_mm IS NULL OR height_mm>=0));
CREATE TABLE package_items(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,package_id UUID NOT NULL,pick_task_id UUID NOT NULL,sales_order_line_id UUID NOT NULL,variant_id UUID NOT NULL,lot_id UUID,serial_id UUID,quantity NUMERIC(19,6) NOT NULL,unit_code VARCHAR(8) NOT NULL,created_at TIMESTAMPTZ NOT NULL,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,package_id)REFERENCES fulfillment_packages(tenant_id,id),FOREIGN KEY(tenant_id,pick_task_id)REFERENCES pick_tasks(tenant_id,id),CHECK(quantity>0));
CREATE UNIQUE INDEX uq_package_serial ON package_items(tenant_id,serial_id)WHERE serial_id IS NOT NULL;CREATE INDEX idx_pick_list_query ON pick_lists(tenant_id,warehouse_id,status,created_at);CREATE INDEX idx_pick_tasks_list ON pick_tasks(tenant_id,pick_list_id,status,sequence);CREATE INDEX idx_pack_items_task ON package_items(tenant_id,pick_task_id);CREATE INDEX idx_packing_sales ON packing_sessions(tenant_id,sales_order_id,status);
INSERT INTO permissions(permission_key,description)VALUES('picking:read','Read pick work'),('picking:manage','Manage pick work'),('packing:read','Read packing work'),('packing:manage','Manage packing work')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name='ORGANIZATION_ADMIN' AND p.permission_key IN('picking:read','picking:manage','packing:read','packing:manage')ON CONFLICT DO NOTHING;INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name IN('READ_ONLY','AUDITOR') AND p.permission_key IN('picking:read','packing:read')ON CONFLICT DO NOTHING;
CREATE TRIGGER reservation_consumptions_immutable BEFORE UPDATE OR DELETE ON inventory_reservation_consumptions FOR EACH ROW EXECUTE FUNCTION prevent_inventory_history_mutation();
ALTER TABLE package_items ADD CONSTRAINT package_items_serial_quantity_check CHECK(serial_id IS NULL OR quantity=1);
CREATE UNIQUE INDEX uq_package_task ON package_items(tenant_id,package_id,pick_task_id);
ALTER TABLE pick_lists ADD CONSTRAINT uq_pick_list_order_destination UNIQUE(tenant_id,id,sales_order_id,warehouse_id,packing_location_id);
ALTER TABLE pick_tasks ADD CONSTRAINT fk_pick_task_list_destination FOREIGN KEY(tenant_id,pick_list_id,sales_order_id,warehouse_id,destination_packing_location_id) REFERENCES pick_lists(tenant_id,id,sales_order_id,warehouse_id,packing_location_id) ON DELETE RESTRICT;
ALTER TABLE pick_lists ADD CONSTRAINT uq_pick_list_session_reference UNIQUE(tenant_id,id,sales_order_id,packing_location_id);
ALTER TABLE packing_sessions ADD CONSTRAINT fk_packing_session_pick_list FOREIGN KEY(tenant_id,pick_list_id,sales_order_id,packing_location_id) REFERENCES pick_lists(tenant_id,id,sales_order_id,packing_location_id) ON DELETE RESTRICT;
